    out = [row[:] for row in grid]
    marker_positions = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    horizontal_rows = {r for r, c in marker_positions if c == 0 or c == w - 1}
    vertical_cols = {c for r, c in marker_positions if r == 0 or r == h - 1}
    rays = {(r, c) for r in horizontal_rows for c in range(w)} | {(r, c) for c in vertical_cols for r in range(h)}
    # Recolor every connected 2-component touched by a marker's full row/column.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            if any(p in rays for p in component):
                for y, x in component:
                    out[y][x] = 1
    for r, c in rays:
        out[r][c] = 1
    return out

