def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    pos={(r,c) for r in range(h) for c in range(w) if grid[r][c]==1}
    rows={r for r in range(h) if (r,0) in pos and (r,w-1) in pos}
    cols={c for c in range(w) if (0,c) in pos and (h-1,c) in pos}
    rays={(r,c) for r in rows for c in range(w)} | {(r,c) for c in cols for r in range(h)}
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and grid[ny][nx]==2 and (ny,nx) not in seen:
              seen.add((ny,nx)); stack.append((ny,nx))
        if any(p in rays for p in comp):
          for y,x in comp: out[y][x]=1
    for r,c in rays: out[r][c]=1
    return out
